static bool g_open;
static int g_cursor_row;

// Geometry of the last drawn panel, in normalized window coordinates, so touch
// input can be hit-tested against it without knowing the buffer size.
static float g_panel_x0, g_panel_y0, g_panel_x1, g_panel_y1;
static float g_rows_y0, g_row_h;

enum ItemKind { kToggle, kChoice };

typedef struct MenuItem {
  const char *label;     // English
  const char *label_es;
  enum ItemKind kind;
  int action;           // if non-zero, the row runs this action
  uint8 *cfg;           // the g_config field it drives
  uint32 feature_bit;   // if non-zero, also toggles this features0 bit
  const char *const *choices;     // English
  const char *const *choices_es;
  int choice_count;
  const uint8 *choice_values;
} MenuItem;

